// ─── Sprint column helpers ────────────────────────────────────────────────────

// Default sprint columns mirror the canonical task statuses. They are the
// fallback for boards that were never customized (and for the virtual
// "No board" board). Once a board's columns are edited they are persisted on
// `board.columns`, each one carrying the chat `status` it groups (and an
// optional Font Awesome `icon`).
function defaultSprintColumns() {
  return $storex.chats.statusList.map(status => ({
    id: status.value,
    title: status.label,
    icon: status.icon,
    color: null,
    profiles: [],
    // Project tasks created in this column are assigned to (optional)
    project_id: null,
    status: status.value
  }))
}

// The chat status a sprint column writes: the explicit `status`, or the UI
// `title` when no status was defined.
function sprintColumnStatus(column) {
  return column?.status || column?.title
}

// Column NAMES identify a column, so they must be unique within a board: two
// columns with the same name are indistinguishable (every lookup by title
// resolves to the first one). The chat `status` a column groups is NOT an
// identity: two or more columns may group the same status and therefore list
// the same tasks.
function sameColumnName(a, b) {
  return `${a || ''}`.trim().toLowerCase() === `${b || ''}`.trim().toLowerCase()
}

// The board column named `title` (case insensitive), excluding the column being
// edited.
function findColumnByName(columns, title, exclude = null) {
  return (columns || []).find(c => c !== exclude && sameColumnName(c.title, title)) || null
}
